import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { importPayloadSchema } from "@/lib/import/schema";
import { buildSantanderPayload, parseSantanderStatement, type SantanderStatement } from "@/lib/import/santander";

// Oracle: test/fixtures/santander/expected.json (generated by scripts/fixture-santander.mjs, checked by
// fixture:check and independently re-derived by scripts/fixture-santander-check.mjs).
const FIXTURES = new URL("../fixtures/santander/", import.meta.url);
const MAIN = "historia_2026-08-31_61109012340001111222233334.csv";
const USD = "historia_2026-08-31_77109056780009998887776665.csv";
const ACCOUNT_NAME = "Rachunek";

interface ExpectedRow {
  file: string;
  line: number;
  occurredOn: string;
  amountMinor: number;
  traps: string[];
  imported: boolean;
  rawMerchant: string;
}
interface Expected {
  files: Record<string, { account: string; imported: { count: number; sumMinor: number } }>;
  rows: ExpectedRow[];
}

const expected = JSON.parse(readFileSync(new URL("expected.json", FIXTURES), "utf8")) as Expected;
const bytesOf = (name: string) => new Uint8Array(readFileSync(new URL(name, FIXTURES)));
const mainRows = expected.rows.filter((r) => r.file === MAIN);

function parseOk(bytes: Uint8Array): SantanderStatement {
  const result = parseSantanderStatement(bytes, { accountName: ACCOUNT_NAME });
  if (!result.ok) throw new Error(`expected ok, got ${result.error}`);
  return result.statement;
}

// Drops line `lineNo` (1-based) from the raw UTF-8 bytes.
function withoutLine(bytes: Uint8Array, lineNo: number): Uint8Array {
  const text = new TextDecoder("utf-8").decode(bytes);
  const hadTrailingNewline = text.endsWith("\n");
  const lines = text.split("\n");
  if (hadTrailingNewline) lines.pop();
  lines.splice(lineNo - 1, 1);
  return new TextEncoder().encode(lines.join("\n") + (hadTrailingNewline ? "\n" : ""));
}

// Replaces data row `lineNo`'s col 1 (operation date, DD-MM-YYYY) with `dmy`. Dates never contain a comma, so
// locating the first two comma boundaries is safe even though later fields may be quoted and contain commas.
function withOperationDate(bytes: Uint8Array, lineNo: number, dmy: string): Uint8Array {
  const text = new TextDecoder("utf-8").decode(bytes);
  const hadTrailingNewline = text.endsWith("\n");
  const lines = text.split("\n");
  if (hadTrailingNewline) lines.pop();
  const line = lines[lineNo - 1];
  const firstComma = line.indexOf(",");
  const secondComma = line.indexOf(",", firstComma + 1);
  lines[lineNo - 1] = line.slice(0, firstComma + 1) + dmy + line.slice(secondComma);
  return new TextEncoder().encode(lines.join("\n") + (hadTrailingNewline ? "\n" : ""));
}

describe("parseSantanderStatement — main fixture", () => {
  const statement = parseOk(bytesOf(MAIN));

  it("reads the one account and the header period (D7)", () => {
    expect(statement.accounts).toHaveLength(1);
    expect(statement.accounts[0].number).toBe(expected.files[MAIN].account);
    expect(statement.accounts[0].name).toBe(ACCOUNT_NAME);
    expect(statement.defaultAccountNumber).toBe(expected.files[MAIN].account);
    expect(statement.period).toEqual({ start: "2026-03-01", end: "2026-08-31" });
  });

  it("reads 187 rows, 184 debits, 3 credits", () => {
    expect(statement.rows).toHaveLength(187);
    const debits = statement.rows.filter((r) => r.amountMinor < 0);
    expect(debits).toHaveLength(184);
    expect(statement.rows.length - debits.length).toBe(3);
    expect(statement.accounts[0]).toMatchObject({ rows: 187, debits: 184, credits: 3 });
  });

  it("builds a payload with 184 debits summing 1342109, source santander, every bankTxId null", () => {
    const payload = buildSantanderPayload(statement, expected.files[MAIN].account);
    expect(payload.source).toBe("santander");
    expect(payload.transactions).toHaveLength(184);
    expect(payload.transactions.reduce((s, t) => s + t.amountMinor, 0)).toBe(1342109);
    expect(payload.transactions.every((t) => t.bankTxId === null)).toBe(true);
    expect(expected.files[MAIN].imported).toEqual({ count: 184, sumMinor: 1342109 });
    expect(importPayloadSchema.safeParse(payload).success).toBe(true);
  });

  it("maps every imported row's date, amount and rule-5 raw merchant, in file order", () => {
    const imported = mainRows.filter((r) => r.imported);
    const debitRows = statement.rows.filter((r) => r.amountMinor < 0);
    expect(debitRows).toHaveLength(imported.length);
    debitRows.forEach((row, i) => {
      const m = imported[i];
      expect(row.occurredOn).toBe(m.occurredOn);
      expect(Math.abs(row.amountMinor)).toBe(Math.abs(m.amountMinor));
      expect(row.counterparty).toBe(m.rawMerchant);
    });
  });

  it("parses the ST15 rows (a bare field holding an unescaped quote) without error", () => {
    const st15 = mainRows.filter((r) => r.traps.includes("ST15"));
    expect(st15.length).toBeGreaterThan(0);
    const debitRows = statement.rows.filter((r) => r.amountMinor < 0);
    for (const r of st15) {
      const row = debitRows.find((d) => d.counterparty === r.rawMerchant);
      expect(row).toBeDefined();
      expect(row?.counterparty).toContain('"');
    }
  });

  // Rule 5's order (CARD tail, else col 3, else col 2) is never exercised by real rows here: a card row's col
  // 3 is always empty (enforced by the generator and the oracle), so the priority is unobservable through the
  // fixture alone. This synthetic row — atypical, col 3 non-empty on a card row — pins the order directly.
  it("rule 5: the CARD tail wins over col 3 even on a (synthetic, atypical) row where both are present", () => {
    const header = '2026-01-31,01-01-2026,\'11 1090 0000 0000 0000 0000 0001,JAN TESTOWY,PLN,"1000,00","990,00",1,';
    const row =
      '30-01-2026,29-01-2026,DOP. VISA 411111******1111 PŁATNOŚĆ KARTĄ 10.00 PLN TEST MERCHANT,ATYPICAL COUNTERPARTY,,"-10,00","990,00",1,';
    const bytes = new TextEncoder().encode(`${header}\n${row}\n`);
    const statement = parseOk(bytes);
    expect(statement.rows).toHaveLength(1);
    expect(statement.rows[0].counterparty).toBe("TEST MERCHANT");
  });

  // Real-only quoting signature `BBQ__QQB_` (Phase 1 shape comparison, impl-review F1): a card description is
  // quoted when its merchant tail holds a comma, and col 3 is empty. The fixture has no such row, so this
  // synthetic one (invented values) pins that the quoted description still yields the CARD tail, comma kept.
  it("rule 5: a quoted card description whose tail holds a comma yields the tail, comma included", () => {
    const header = '2026-01-31,01-01-2026,\'11 1090 0000 0000 0000 0000 0001,JAN TESTOWY,PLN,"1000,00","990,00",1,';
    const row =
      '30-01-2026,29-01-2026,"DOP. VISA 411111******1111 PŁATNOŚĆ KARTĄ 10.00 PLN SKLEP TESTOWY, MIASTO",,,"-10,00","990,00",1,';
    const statement = parseOk(new TextEncoder().encode(`${header}\n${row}\n`));
    expect(statement.rows).toHaveLength(1);
    expect(statement.rows[0].counterparty).toBe("SKLEP TESTOWY, MIASTO");
  });
});

describe("parseSantanderStatement — USD fixture and broken input", () => {
  it("rejects the USD file as wrong-currency", () => {
    expect(parseSantanderStatement(bytesOf(USD), { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "wrong-currency",
    });
  });

  it("rejects the main file missing one data row (header col 7 mismatch)", () => {
    const broken = withoutLine(bytesOf(MAIN), mainRows[5].line);
    expect(parseSantanderStatement(broken, { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });

  it("rejects an operation date moved before the header start (R1)", () => {
    const row = mainRows[10];
    const broken = withOperationDate(bytesOf(MAIN), row.line, "15-02-2026");
    expect(parseSantanderStatement(broken, { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });

  it('rejects a `""` escape attempt inside a quoted field', () => {
    const header = '2026-01-31,01-01-2026,\'11 1090 0000 0000 0000 0000 0001,JAN TESTOWY,PLN,"1000,00","900,00",1,';
    const row = '30-01-2026,29-01-2026,"A""B",KONTRAHENT TESTOWY,,"-100,00","900,00",1,';
    const bytes = new TextEncoder().encode(`${header}\n${row}\n`);
    expect(parseSantanderStatement(bytes, { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });

  it("rejects the ING main fixture's bytes (cp1250, not strict UTF-8)", () => {
    const ingBytes = readFileSync(
      new URL("../fixtures/ing/Lista_transakcji_nr_0000123456_010926.csv", import.meta.url),
    );
    expect(parseSantanderStatement(new Uint8Array(ingBytes), { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });

  it("rejects the main file with one multi-byte character corrupted (what a cp1250 re-save would leave behind)", () => {
    // The card description "PŁATNOŚĆ KARTĄ" encodes "Ł" as the two-byte UTF-8 sequence 0xC5 0x81. Breaking its
    // continuation byte reproduces exactly what re-saving as windows-1250 (ANSI) does to every such character:
    // bytes that no longer decode as strict UTF-8.
    const bytes = bytesOf(MAIN);
    const corrupted = new Uint8Array(bytes);
    const at = corrupted.findIndex((b, i) => b === 0xc5 && corrupted[i + 1] === 0x81);
    expect(at).toBeGreaterThan(-1);
    corrupted[at + 1] = 0x41; // ASCII 'A' is not a UTF-8 continuation byte
    expect(parseSantanderStatement(corrupted, { accountName: ACCOUNT_NAME })).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });
});
